use b27_primitives::stream;
#[test]fn integrity(){let mut x=vec![1;stream::BLOCK];x.extend(vec![2;stream::BLOCK]);let mut y=vec![];stream::encode(&x[..],&mut y,4).unwrap();let mut z=vec![];stream::decode(&y[..],&mut z,x.len()as u64).unwrap();assert_eq!(x,z);let n=u32::from_be_bytes(y[4..8].try_into().unwrap())as usize+4;let p=4+n;let m=u32::from_be_bytes(y[p..p+4].try_into().unwrap())as usize+4;let mut swapped=y[..4].to_vec();swapped.extend_from_slice(&y[p..p+m]);swapped.extend_from_slice(&y[4..p]);swapped.extend_from_slice(&y[p+m..]);assert!(stream::decode(&swapped[..],Vec::new(),u64::MAX).is_err());let mut deleted=y[..4].to_vec();deleted.extend_from_slice(&y[p..]);assert!(stream::decode(&deleted[..],Vec::new(),u64::MAX).is_err());let mut bad=y.clone();let last=bad.len()-1;bad[last]^=1;assert!(stream::decode(&bad[..],Vec::new(),u64::MAX).is_err());}
